async function saveLibrary(e){e.preventDefault();const ed=editingLib,d=ed.draft,list=ed.kind==='camera'?p().cameras:p().lenses;if(!d.code?.trim()||!d.model?.trim())return toast('An ID and model are required.');if(list.some(x=>x.id!==ed.id&&x.code===d.code.trim()))return toast('That equipment ID already exists.');if(d.fps!==undefined&&d.fps!==null&&(!Number.isFinite(d.fps)||d.fps<=0))return toast('FPS must be a positive number.');d.code=d.code.trim();d.id=ed.id||uid();d.provenance=ed.provenance;const at=list.findIndex(x=>x.id===d.id);if(at<0)list.push(d);else list[at]=d;await save();go('library',{},true);toast(pretty(ed.kind)+' saved')}
function confirmLibraryDelete(){const ed=editingLib,key=ed.kind==='camera'?'cameraId':'lensId',count=shots().filter(h=>h.camera?.[key]===ed.id).length;$('dlgBody').innerHTML='<h2>Delete '+esc(ed.draft.code)+'?</h2><p>'+esc(ed.draft.code)+' is used by '+count+' shots.</p><p class="helper">The equipment will be unassigned. Recorded camera-state values remain.</p><div class="row"><button onclick="closeDlg()">Cancel</button><button class="danger-fill" onclick="deleteLibrary()">Delete and unassign</button></div>';$('dlg').showModal()}
