async function deleteProject(){if($('deleteCode').value!==p().code)return;const project=p(),mediaIds=new Set(shots().flatMap(h=>[...(h.media||[]),...(h.plates||[]),...(h.voice||[])].map(m=>m.mediaId)));const next=structuredClone(state);next.projects=next.projects.filter(x=>x.id!==project.id);next.activeProjectId=null;next.activeShotId=null;await new Promise((resolve,reject)=>{const tx=db.transaction(['kv','media'],'readwrite');tx.objectStore('kv').put(next,'state');const os=tx.objectStore('media');for(const id of mediaIds)if(id)os.delete(id);const req=os.openCursor();req.onsuccess=()=>{const cur=req.result;if(cur){if(cur.value.projectId===project.id)cur.delete();cur.continue()}};tx.oncomplete=resolve;tx.onerror=e=>reject(tx.error||e.target.error||new Error('Storage write failed'));tx.onabort=()=>reject(tx.error||new Error('Storage transaction aborted'))});state=next;closeDlg();navStack=[];go('projects',{},true);toast('Project deleted')}
function capture(){if(captureSaving)return toast('Saving capture…');const h=raw();captureContext={projectId:p().id,shotId:h.id,take:h.take,created:now()};$('captureInput').value='';$('captureInput').click()}
