async function saveMeasurement(e){e.preventDefault();const value=Number($('mv').value),unit=$('mu').value,factor={m:1,cm:.01,mm:.001,ft:.3048,in:.0254,deg:Math.PI/180};if(!Number.isFinite(value))return;if($('mm').value==='OTHER'&&!$('mmCustom').value.trim())return toast('Enter the custom method.');raw().measurements.push({id:uid(),from:$('mf').value.trim(),to:$('mt').value.trim(),value,unit,si:{value:value*factor[unit],unit:unit==='deg'?'rad':'m'},method:$('mm').value==='OTHER'?$('mmCustom').value.trim():$('mm').value,confidence:$('mc').value,take:route.captureTake,created:now()});await save();back();toast('Measurement saved')}
