function toolsScreen(){const list=[['screen','Screen assets','Green & blue · fullscreen, share, PNG'],['markers','Tracking markers','Cross, circle & checker · physical sizes'],['distortion','Lens distortion','Uniform grid · camera & lens context'],['scale','Scale references','Metric reference · print at actual size']];$('main').innerHTML='<section class="hero"><div class="eyebrow accent">ON-SET UTILITIES</div><h1>Built for<br>the real world.</h1><p class="lead">From a screen in the frame to a marker on the set.</p></section><div class="list">'+list.map(([id,t,s],i)=>row(t,s,"go('"+id+"')",'','<span class="tool-index">0'+(i+1)+'</span>')).join('')+'</div>'}
let screenSettings={color:'GREEN',pattern:'5POINT',aspect:'16:9',width:1920,height:1080},screenBlob=null;
function screenAssetScreen(){$('main').innerHTML=pageTop('Screen assets','Tools')+selectField('assetColor','Color',[['GREEN','Green'],['BLUE','Blue']],screenSettings.color,'onchange="screenSettings.color=this.value;drawAsset()"')+selectField('assetPattern','Pattern',[['NONE','None'],['4CORNERS','4 corners'],['5POINT','5 point'],['GRID','Grid']],screenSettings.pattern,'onchange="screenSettings.pattern=this.value;drawAsset()"')+selectField('assetAspect','Aspect',[['16:9','16:9'],['9:16','9:16'],['19.5:9','19.5:9'],['4:3','4:3'],['CUSTOM','Custom']],screenSettings.aspect,'onchange="screenSettings.aspect=this.value;document.getElementById(\'assetCustom\').hidden=this.value!==\'CUSTOM\';drawAsset()"')+'<div id="assetCustom" '+(screenSettings.aspect==='CUSTOM'?'':'hidden')+'>'+field('assetWidth','Width / px',screenSettings.width,'number','min="64" max="4096" step="1" onchange="screenSettings.width=Number(this.value);drawAsset()"')+field('assetHeight','Height / px',screenSettings.height,'number','min="64" max="4096" step="1" onchange="screenSettings.height=Number(this.value);drawAsset()"')+'</div><div class="preview-wrap"><canvas id="assetCanvas" aria-label="Screen asset preview"></canvas></div><p class="helper" id="assetSize"></p><div class="button-stack"><button class="primary" onclick="fullscreenAsset()">Fullscreen</button><button class="secondary" onclick="shareAsset()">Share</button><button class="secondary" onclick="saveAsset()">Save PNG</button></div>';drawAsset()}
function drawAsset(){const c=$('assetCanvas');if(!c)return;let w,h;if(screenSettings.aspect==='CUSTOM'){w=screenSettings.width;h=screenSettings.height;if(!Number.isInteger(w)||!Number.isInteger(h)||w<64||h<64||w>4096||h>4096){$('assetSize').textContent='Use whole dimensions between 64 and 4096 px.';screenBlob=null;return}}else{const [a,b]=screenSettings.aspect.split(':').map(Number);w=a>=b?1920:Math.round(1920*a/b);h=a>=b?Math.round(1920*b/a):1920}c.width=w;c.height=h;const ctx=c.getContext('2d'),green=screenSettings.color==='GREEN';ctx.fillStyle=green?'#00b83c':'#0648e8';ctx.fillRect(0,0,w,h);ctx.strokeStyle=green?'#007c2a':'#12329a';ctx.lineWidth=Math.max(3,Math.min(w,h)*.006);const points=[],a=.13,b=.87;if(['4CORNERS','5POINT'].includes(screenSettings.pattern))points.push([a,a],[b,a],[a,b],[b,b]);if(screenSettings.pattern==='5POINT')points.push([.5,.5]);if(screenSettings.pattern==='GRID')for(let x=1;x<6;x++)for(let y=1;y<4;y++)points.push([x/6,y/4]);const len=Math.min(w,h)*.022;for(const [x,y] of points){ctx.beginPath();ctx.moveTo(w*x-len,h*y);ctx.lineTo(w*x+len,h*y);ctx.moveTo(w*x,h*y-len);ctx.lineTo(w*x,h*y+len);ctx.stroke()}$('assetSize').textContent=w+' × '+h+' px · chroma-family tracking points';const version=++assetVersion;screenBlob=null;c.toBlob(b=>{if(version===assetVersion)screenBlob=b},'image/png')}
let assetVersion=0;
function assetName(){return [p().code,shot()?.code,screenSettings.color,screenSettings.aspect==='CUSTOM'?screenSettings.width+'x'+screenSettings.height:screenSettings.aspect.replace(':','x'),screenSettings.pattern].filter(Boolean).join('_')+'.png'}
function saveAsset(){if(!screenBlob)return toast('Wait for a valid preview.');dl(assetName(),screenBlob)}
