function fullscreenAsset(){if(!screenBlob)return;const overlay=document.createElement('div');overlay.className='full-asset';overlay.style.background=screenSettings.color==='GREEN'?'#00b83c':'#0648e8';overlay.id='assetFullscreen';const canvas=document.createElement('canvas'),source=$('assetCanvas');canvas.width=source.width;canvas.height=source.height;canvas.getContext('2d').drawImage(source,0,0);overlay.append(canvas);const exit=document.createElement('button');exit.textContent='Exit fullscreen';exit.onclick=closeFullscreen;overlay.append(exit);document.body.append(overlay);overlay.requestFullscreen?.().catch(()=>{});exit.focus()}
