async function printMarkers(){const count=Number($('markerCount').value),size=Number($('markerSize').value),style=$('markerStyle').value,paper=$('markerPaper').value,signature=[count,size,style,paper].join('|');if(route.markerSignature!==signature){const start=p().nextMarkerId||1;p().nextMarkerId=start+count;route.markerStart=start;route.markerSignature=signature;await save()}const width=paper==='A4'?210:215.9,height=paper==='A4'?297:279.4,cols=Math.max(1,Math.floor((width-10+8)/(size+8))),rows=Math.max(1,Math.floor((height-10+8)/(size+22))),per=cols*rows;let pages=[];for(let start=0;start<count;start+=per){let items=[];for(let i=start;i<Math.min(start+per,count);i++){let id=p().code+'-TRK-'+String(route.markerStart+i).padStart(3,'0');items.push('<div class="print-marker" style="width:'+size+'mm"><div style="width:'+size+'mm;height:'+size+'mm">'+markerSVG(style)+'</div><div class="print-label">'+esc(id)+' · '+size+' mm</div></div>')}pages.push('<section class="marker-sheet '+(start+per<count?'print-page':'')+'">'+items.join('')+'</section>')}preparePrint(pages.join(''),paper,5)}
function distortionSVG(){let lines='';for(let x=0;x<=180;x+=10)lines+='<path d="M'+x+' 0V240"/>';for(let y=0;y<=240;y+=10)lines+='<path d="M0 '+y+'H180"/>';return '<svg xmlns="http://www.w3.org/2000/svg" class="print-grid" viewBox="0 0 180 240"><rect width="180" height="240" fill="white" stroke="none"/><g stroke="black" stroke-width=".55">'+lines+'</g><path d="M80 120h20M90 110v20" stroke="black" stroke-width="1.5"/><circle cx="90" cy="120" r="5" fill="white" stroke="black" stroke-width=".75"/><path d="M87 120h6M90 117v6" stroke="black" stroke-width=".8"/></svg>'}
function distortionScreen(){const c=raw()?.camera||{};$('main').innerHTML=pageTop('Lens distortion','Tools')+'<p class="helper">Uniform grid with a center crosshair. The current shot supplies the context.</p>'+selectField('gridPaper','Paper',paperOptions,'A4')+'<div class="settings">'+[['Camera',cam(c.cameraId)],['Lens',lens(c.lensId)],['Focal',c.focal!=null?c.focal+' mm':'—'],['Focus',c.focus!=null?c.focus+' m':'—'],['Sensor mode',c.sensorMode||'—']].map(([k,v])=>'<div class="setting"><label>'+k+'</label><span style="max-width:65%;text-align:right">'+esc(v)+'</span></div>').join('')+'</div><div class="preview-wrap" style="height:300px;aspect-ratio:auto;padding:16px">'+distortionSVG()+'</div><button class="primary action" onclick="printDistortion()">Print / Save PDF</button>'}
function printDistortion(){const c=raw()?.camera||{},paper=$('gridPaper').value;preparePrint('<div class="print-label">SLYHIGH VFX Tools · '+esc(p().code)+' / '+esc(shot()?.code||'')+'<br>'+esc(cam(c.cameraId))+' · '+esc(lens(c.lensId))+'<br>Focal '+esc(c.focal??'—')+' mm · Focus '+esc(c.focus??'—')+' m · Sensor '+esc(c.sensorMode||'—')+'</div><div style="width:170mm;height:226.67mm">'+distortionSVG()+'</div>',paper,10)}
function scaleScreen(){$('main').innerHTML=pageTop('Scale references','Tools')+'<p class="helper">100 mm reference with 10 mm divisions. Verify with a physical ruler after printing.</p>'+selectField('scalePaper','Paper',paperOptions,'A4')+'<div class="preview-wrap" style="padding:20px">'+scaleSVG()+'</div><button class="primary action" onclick="printScale()">Print / Save PDF</button>'}
function scaleSVG(){return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 110 35"><rect width="110" height="35" fill="white" stroke="none"/>'+Array.from({length:10},(_,i)=>'<rect x="'+(5+i*10)+'" y="8" width="10" height="10" fill="'+(i%2?'white':'black')+'" stroke="black" stroke-width=".3"/>').join('')+'<path d="M5 5v18M105 5v18" stroke="black" stroke-width=".3"/><text x="55" y="29" text-anchor="middle" fill="black" stroke="none" font-family="Arial" font-size="5">100 mm</text></svg>'}
function printScale(){preparePrint('<h2>SLYHIGH VFX Tools · Scale reference</h2><p>'+esc(p().code)+' · Print at actual size / 100%.</p><div style="width:110mm;height:35mm">'+scaleSVG()+'</div>',$('scalePaper').value)}
function exportScreen(){$('main').innerHTML='<section class="hero"><div class="eyebrow accent">'+esc(p().code)+' / EXPORT</div><h1>Ready for<br>post.</h1><p class="lead">Structured data. The full context.</p></section><div class="list">'+row('Project JSON','Full structured project metadata',"exportJSON()")+row('Shot CSV','Camera states & acquisition counts',"exportCSV()")+row('Project backup','Metadata + original media in one file',"exportBackup()")+(shot()?row('Shot report / PDF',shot().code+' · same-screen print',"report()"):'')+'</div><p class="footer-note">slyhigh.vfxdata / '+VER+'<br>JSON and CSV contain metadata. Use project backup to include original photos and videos.</p>'}
function report(){const h=shot(),r=raw(),c=r.camera||{},rows=Object.entries(c).filter(([k])=>!['cameraId','lensId','updated'].includes(k));preparePrint('<p>SLYHIGH VFX Tools · '+esc(p().code)+'</p><h1>'+esc(r.code)+'</h1><p>'+esc(h._d.date)+' · SC '+esc(h._s.code)+' · SETUP '+esc(h._u.code)+' · TAKE '+r.take+'</p><table><tr><th>Camera</th><td>'+esc(cam(c.cameraId))+'</td></tr><tr><th>Lens</th><td>'+esc(lens(c.lensId))+'</td></tr>'+rows.map(([k,v])=>'<tr><th>'+esc(pretty(k))+'</th><td>'+esc(v??'—')+'</td></tr>').join('')+'</table><h2>Measurements</h2><table>'+r.measurements.map(m=>'<tr><td>Take '+esc(m.take)+'</td><td>'+esc(m.from)+' → '+esc(m.to)+'</td><td>'+esc(m.value)+' '+esc(m.unit)+'</td><td>'+esc(m.method)+' / '+esc(m.confidence)+'</td></tr>').join('')+'</table><h2>Notes</h2>'+r.notes.map(n=>'<p><b>TAKE '+esc(n.take)+'</b> '+esc(n.text)+'</p>').join('')+'<h2>References</h2>'+r.media.map(m=>'<p>TAKE '+esc(m.take)+' · '+esc(m.tag)+' · '+esc(m.note)+'</p>').join('')+'<p>Generated '+esc(new Date().toLocaleString())+'</p>')}
async function exportBackup(){toast('Preparing backup with original media…');const data=payload(),all=shots(data.project),ids=[...new Set(all.flatMap(h=>[...(h.media||[]),...(h.plates||[]),...(h.voice||[])].map(m=>m.mediaId)).filter(Boolean))];const media=[];for(const id of ids){const entry=await get('media',id);if(!entry){toast('Backup stopped: a media file is missing.');return}const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(mediaBlob(entry))});const {blob,bytes,...meta}=entry;media.push({...meta,data:encoded})}dl(data.project.code+'_VFX_BACKUP.json',new Blob([JSON.stringify({...data,backup_format:'slyhigh.media-backup.1',media})],{type:'application/json'}));toast('Backup ready')}
window.addEventListener('unhandledrejection',e=>{console.error(e.reason);setSaveStatus('ACTION FAILED · RETRY',true)});
async function init(){try{await openDB();await load();state.projects||=[];for(const pr of state.projects){pr.cameras||=[];pr.lenses||=[];pr.days||=[];for(const h of shots(pr)){// Fill absent collections on the stored object without replacing existing data.
for(const d of pr.days)for(const s of d.scenes)for(const u of s.setups){const r=u.shots.find(x=>x.id===h.id);if(r){for(const k of ['types','media','measurements','notes','plates','voice'])r[k]||=[];r.camera||={};r.take||=1}}}}
route={page:p()?(shot()?'shot':'shoot'):'projects',projectId:state.activeProjectId,shotId:state.activeShotId};history.replaceState({sly:true},'');if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();setSaveStatus('ON DEVICE');if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});window.visualViewport?.addEventListener('resize',()=>document.body.classList.toggle('keyboard',window.visualViewport.height<window.innerHeight*.75))}catch(e){$('main').innerHTML='<section class="hero"><h1>Storage unavailable.</h1><p class="lead">Allow browser storage, then reload to open your projects.</p><button class="primary action" onclick="location.reload()">Retry</button></section>';console.error(e)}}init();


function renderCaptureDock(){let dock=$('captureDock');if(!dock){dock=document.createElement('div');dock.id='captureDock';document.body.append(dock)}const show=route.page==='shot'&&raw();document.body.classList.toggle('has-capture-dock',!!show);dock.hidden=!show;if(show)dock.innerHTML='<span><small>CURRENT TAKE</small><b>'+String(raw().take||1).padStart(2,'0')+'</b></span><button class="primary" onclick="capture()">'+icon('camera')+' Capture photo / video</button>'}
